mapper.select:
SELECT U.*, S.ShopName AS ShopName FROM shopwizard.tOrdOrderUprice U LEFT OUTER JOIN shopwizard.tCmpShop S ON S.ShopCode = U.ShopCode
ORDER BY U.Keywrd, U.Capa, U.MatchUpriceCode
LIMIT ${pPageOffset}, ${pPageSize}

SELECT U.*, S.ShopName AS ShopName
FROM shopwizard.tOrdOrderUprice U
LEFT OUTER JOIN shopwizard.tCmpShop S ON S.ShopCode = U.ShopCode

    AND U.MatchUpriceCode = #{matchUpriceCode}
    AND U.MatchUpriceCode != #{pMatchUpriceCode}
    AND U.OrderProdName = #{pOrderProdName}
    AND U.UseYn = #{pUseYn}

LIMIT 1

SELECT COUNT(*) FROM shopwizard.tOrdOrderUprice
WHERE IFNULL(ShopCode, '') = IFNULL(#{shopCode}, '') AND OrderProdName = #{orderProdName} AND UseYn = #{useYn}
  AND MatchUpriceCode <> #{excludeCode}
